WITH unpacked AS (SELECT id, plan, effective_from, tier_prices, discounts, SLICE(tier_limits, 1, 2) AS first_two_limits, AGGREGATE(tier_prices, 0.0D, (acc, p) -> acc + p, acc -> ROUND(acc / SIZE(tier_prices), 2)) AS avg_tier_price, ARRAY_MIN(tier_prices) AS lowest_price, TRANSFORM(tier_prices, (p, i) -> ROUND(p * tier_limits[i], 2)) AS tier_revenue_caps, ZIP_WITH(tier_prices, discounts, (p, d) -> ROUND(p * (1 - d), 2)) AS net_prices FROM price_tiers) SELECT *, NTILE(10) OVER (PARTITION BY plan ORDER BY avg_tier_price DESC, id) avg_tier_price_bucket, AVG(avg_tier_price) OVER (PARTITION BY plan ORDER BY effective_from, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) avg_tier_price_avg_6, LAST_VALUE(avg_tier_price, TRUE) OVER (PARTITION BY plan ORDER BY avg_tier_price, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) last_known_avg_tier_price FROM unpacked
